UPDATE courses SET
    course_description = '<p>Kick start your career in the civil construction industry with the Diploma of Civil Construction Design. This qualification prepares you for work as a designer or design paraprofessional who supports professional engineers. This course prepares you to perform tasks involving a high level of autonomy and requiring significant judgement in planning and selecting equipment/roles/techniques.</p> <p>You are required to develop site-specific work designs to ensure the implementation of clients’ site requirements. You will learn to use 2D and 3D industry software applications such as AutoCAD and Revit, which are essential tools for designing construction and infrastructure projects.</p>',
    total_course_duration = '1.5 year',
    offshore_tuition_fee = '18300',
    entry_requirements = '<p>IELTS 5.5 or equivalent</p> <p>18 years or older</p> <p>Completion of Year 12 studies or equivalent</p> <p>Please see our <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-civil-construction-design',
    updated_at = NOW()
WHERE cricos_course_code = '108711E';


UPDATE courses SET
    course_description = '<p>This qualification prepares you for work as a senior civil works designer or a para-professional designer, who supports professional engineers in the design and construction of infrastructure projects. This course will teach you to perform broad, specialised, complex and technical tasks.</p> <p>You will be responsible for the design of complex projects to ensure the implementation of clients’ site requirements. You will be required to demonstrate self-directed application of theoretical and technical knowledge and initiate solutions to technical problems or management requirements.</p> <p>You will develop skills in:</p> <p>Using computer-aided design (CAD) software including AutoCAD and REVIT to produce detailed drawings, plans and designs for construction work</p> <p>Preparing civil designs</p> <p>Managing the civil works design process</p> <p>Construction management to meet the needs of the Australian market</p>',
    total_course_duration = '2 year',
    offshore_tuition_fee = '24000',
    entry_requirements = '<p><b>Pre-requisite:</b></p> <p> Diploma of Civil Construction Design (RII50520)</p> <p>IELTS 5.5 or equivalent</p> <p>18 years or older</p> <p>Completion of Year 12 studies or equivalent</p> <p>Please see <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/advanced-diploma-of-civil-construction-design',
    updated_at = NOW()
WHERE cricos_course_code = '105230B';


UPDATE courses SET
    course_description = '<p>Social work is an academic, practice-based profession that promotes social change and development, social cohesion, and the empowerment and liberation of people (AASW Practice Standards 2013). Consistent with this statement, upon completing the course, you will be equipped with a sound knowledge of the underlying principles, concepts, and critical skills in social work as well as demonstrated capabilities in critical thinking, ethical and reflective practice, and continuous professional development. The Master of Social Work (Qualifying) will incorporate theoretical content that builds on knowledge acquired in previous higher education.</p> <p>In line with the accreditation standards set out by the AASW (ASWEAS 2021), the Master of Social Work (Qualifying) course will prepare you with the requisite theoretical knowledge, skills, and ethical framework for social work practice within diverse client systems across various practice contexts. This two-year course will encompass required AASW (ASWEAS 2021) core curriculum content on constructions of social work purpose, place, and practice; power, oppression, and exploitation; culture, identity, and discrimination; psychosocial health and wellbeing across the life course; and working with First Nations people including Aboriginal and Torres Strait Islander peoples and communities. The course will focus on assisting individuals, groups, and communities at the personal and structural levels to bring about positive social change. In keeping with this dual focus, the contemporary curriculum is ensconced within a human rights and social justice framework and the Master of Social Work (Qualifying) will develop your knowledge about a wide range of fields and methods of social work practice, including direct practice, social policy and research, group work, community development, management, and leadership, while at the same time situating this knowledge to take into account local, national, international, and global trends.</p> <p>You will be encultured into the profession of social work through an integrated curriculum that merges direct practice with leadership and advocacy social work roles within a contemporary and transformative approach to practice and social change. Field education through placements will contribute to opportunities for experiential learning, application, and development of theoretical knowledge and understanding across a variety of workplace settings where social work takes place. Experiential learning via classroom activities, online activities, and field practicums will assist you in linking theory to practice and applying learning to practice.</p>',
    total_course_duration = '2 year',
    offshore_tuition_fee = '26200',
    entry_requirements = '<p>Psychology, including psychology research and policy</p> <p>Counselling/therapeutic roles in areas such as play therapy, rehabilitation counselling, art therapy, disability, and inclusion</p> <p>Specialist clinical areas such as child development, drug and alcohol, working with ageing/disability populations, emergency services, education, family violence</p> <p>Allied health areas such as nursing/midwifery, health promotion, occupational/speech/physiotherapy, occupational health, audiology</p> <p>Anthropology</p> <p>Community development</p> <p>Criminology</p> <p>Economics with a health/social focus</p> <p>First Nation/Indigenous studies</p> <p>Geography</p> <p>International relations</p> <p>Legal studies with a health/social focus</p> <p>Politics/political sciences</p> <p>Public health</p> <p>Sociology/social sciences</p> <p>Sustainability with a health/social focus</p> <p>Completed a Year 12 or equivalent secondary school qualification in English. <b><u>or</u></b></p> <p>Completed a higher qualification in English as the medium of instruction, consistent with the requirements for admission to a Level 9 degree course in Australia. <b><u>or</u></b></p> <p>Achieved a minimum score of 7.0 or higher in each component (listening, reading, writing, and speaking) of the Academic International English Language Testing System (IELTS) test, or equivalent, upon course commencement.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/master-of-social-work-qualifying',
    updated_at = NOW()
WHERE cricos_course_code = '116234G';


UPDATE courses SET
    course_description = '<p>The Bachelor of Community Services is a fully accredited Australian higher education degree. The course is designed to prepare you for ethical, competent, and culturally relevant community service generalist practice and to equip you with the skills you need for life-long learning and professional development. You will work at the interface between people and their environments, focusing on the experiences of individuals, families, groups and communities. Areas of service provision include child welfare, hospice and palliative care, and juvenile justice and corrections and advocacy.</p> <p>You will learn about the theory and values base of human services practice, as well as the knowledge and skills required to work as a professional at a managerial level in the community services sector. You will have the foundational knowledge and skills in community services management you need to continue to a relevant post-graduate higher education program at a university or private education provider.</p>',
    total_course_duration = '3 year',
    offshore_tuition_fee = '2475',
    entry_requirements = '<p>National Police Record Check and/or Police clearance from country of residence</p> <p>Working with Children Check</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-community-services',
    updated_at = NOW()
WHERE cricos_course_code = '096281C';


UPDATE courses SET
    course_description = '<p>The Graduate Certificate of Health and Community is designed for health &amp; community services professionals who wish to advance their careers, or for those who want to enter a new career in this growing industry sector. The course also offers a pathway into the Master of Social Work (Qualifying) degree at Acknowledge Education.</p> <p>The Graduate Certificate of Health and Community provides a broad-based knowledge of health and community services, its practices, processes, and underlying theories and principles. The theoretical and applied learning units in this course, are designed so that students gain real-world knowledge and skills for application when working in health and community service contexts.</p>',
    total_course_duration = '14 weeks',
    offshore_tuition_fee = '3075',
    entry_requirements = '<p><b>Academic Requirements</b></p> <p>To be accepted into the course, international students require a relevant three-year AQF Level 7 degree.</p> <p><b>English Requirements</b></p> <p>International students must have an IELTS (Academic) minimum overall band score of 6.5 (with no individual band below 6.0) or equivalent completed within the two years prior to admission.</p> <p>Please click <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">here</a> to download Admissions Policy for Overseas Students (HE and VET) .</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/graduate-certificate-of-health-and-community',
    updated_at = NOW()
WHERE cricos_course_code = '115053J';


UPDATE courses SET
    course_description = '<p>The Bachelor of Tourism and Hospitality Management course is a fully accredited Australian higher education degree. The course aims to prepare you to be a competent, knowledgeable and professional candidate for a generalist, entry-level management position in either the tourism or hospitality industry. The Bachelor of Tourism and Hospitality Management course is designed with a strong emphasis on ‘client focus’ and adherence to principles of ethics and sustainability in the industry as part of their professional practice. The course also aims to create an industry professional who is versatile and adaptable with a diverse skill base and ability to adapt to an ever-changing business environment in an increasing global marketplace.</p>',
    total_course_duration = '3 years',
    offshore_tuition_fee = '2250',
    entry_requirements = '<p>be at least 18 years old, AND</p> <p>have completed Year 12 or equivalent.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-tourism-and-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '103455A';


UPDATE courses SET
    course_description = '<p>Kick-start your career confidently in different roles within the construction industry, from planning and design to development, construction, and operation.</p> <p>Acknowledge Education’s Bachelor of Construction Project Management equips you with the job-ready skills and knowledge in managing residential, commercial, and industrial construction projects.</p> <p>You will graduate with skills in:</p> <p>Construction management</p> <p>Construction technology</p> <p>Quantity surveying</p> <p>Construction law and contracts</p> <p>Building services, surveying, and sustainable practices</p> <p>Cost and quality management</p>',
    total_course_duration = '3 year',
    offshore_tuition_fee = '2550',
    entry_requirements = '<p>You must have completed Year 12 or equivalent. The minimum age is 18 years old.</p> <p>International students must also demonstrate that they have English language ability equivalent to IELTS 6.0 (Academic).</p> <p>Competency to IELTS 6.0 means that the student has documentary evidence of having completed an IELTS exam at an official IELTS testing centre, or an equivalent recognised English language test, within the 24 months preceding the student’s application date for Bachelor’s courses, and that the student was given an overall score of 6 with no single band lower than 5.5 (see our <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admission Policy</a>).</p> <p><b>Applying for Credit Transfer:</b></p> <p>If you have completed prior tertiary studies, you may be eligible for some credit exemptions. For further information, please refer to our <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">Awarding of Credit Policy</a>.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-construction-project-management',
    updated_at = NOW()
WHERE cricos_course_code = '111660G';


UPDATE courses SET
    course_description = '<p>Counselling has developed substantially over the past decade. It is increasingly being recognised for its efficacy in practice, and for its more practical educational and therapeutic approach. This has positioned counselling as a more attractive career option than its more science- and statistics-based mental health peers.</p> <p>Combined with our industry-leading support services and teaching methods, AE fully supports you in your study of advanced counselling topics to develop your skills as a counselling professional.</p> <p><b>The Master of Counselling is</b> <b>designed and developed by Australian Institute of Professional Counsellors (AIPC); Higher Education Provider Number: PRV12083, CRICOS Provider Code: 04095M. The course is being delivered through third party arrangements between Acknowledge Education(AE) and Australian Institute of Professional Counsellors (AIPC). AE delivers the course on behalf of AIPC.</b></p> <p>The Master of Counselling teaches contemporary counselling topics and skills to an advanced level and is ideally suited to counsellors wanting to develop their knowledge and skills to a higher level, or professionals aspiring to pursue a career in this high-demand industry.</p>',
    total_course_duration = '2 year',
    offshore_tuition_fee = '3090',
    entry_requirements = '<p>IELTS: Overall Band Score of 6.5 in the Academic IELTS with a minimum of 6.0 in each band, or</p> <p>TOEFL (iBT): Overall score 82 or better with a minimum of 20 in the writing band, or</p> <p>PTE Academic: Overall score of 58 with a minimum score of 50 in each band, or</p> <p>Cambridge English Scale score: 176. No less than 169 in any paper, or</p> <p>At least one year of University studies in Australia in the last two years, or</p> <p>Evidence of at least 5 years of studies in an English speaking country (Australia, New Zealand, UK, Canada, USA, South Africa or Ireland), or</p> <p>Australian Year 12 Certificate or qualification at Certificate IV or higher level completed in the last two years, or, </p> <p>Acknowledge Education English Test, or equivelent</p> <p>COVID-19 Vaccination Record</p> <p>National Police Record Check and/or Police clearance from country of residence</p> <p>Working with Children Check</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/master-of-counselling',
    updated_at = NOW()
WHERE cricos_course_code = '112554A';


UPDATE courses SET
    course_description = '<p>If your passion is human rights and social justice, and changing lives for the better this course is for you. Our four-year BSW informed by trends in international and local contexts where social work takes place has a contemporary curriculum designed to develop your knowledge and skills for creating meaningful change with individuals, families, groups, communities, and organisations. Importantly, as you undertake your studies you will learn to critique and respond to social injustices, reflect on your practice, and develop yourself as a professional social worker. </p> <p>In addition, careers in social work are growing with Job Skills Australia suggesting that future job opportunities within the social work field will grow by 23.2% by 2026. </p> <p>The Bachelor of Social Work (BSW) has been designed and developed by Acknowledge Education, a leading Institute of Higher Education (PRV 12146). The <a class="rich-text-link" href="https://www.aipc.net.au/courses/bachelor-of-social-work" rel="noreferrer" target="_blank"><b>Australian Institute of Professional Counsellors (AIPC)</b></a> delivers the course on behalf of Acknowledge Education. </p> <p>Social Work is a wonderful profession focused on bringing about real change in the lives of the people and communities with which we work. Social Work is a career that has a real impact on the world. Come and join us to begin your journey towards a career full of meaning and purpose. </p>',
    total_course_duration = '4 years',
    offshore_tuition_fee = '',
    entry_requirements = '<p>VCE or equivalent with a score of no less than 30 in EAL or other English course; OR</p> <p>Successful completion of a Diploma (minimum 1 year) or an Advanced Diploma course taught in English in Australia AND have passed an AE internal English test; OR</p> <p>Successful completion of 1 year of a Bachelor degree or higher taught in Australia AND have passed an AE internal English test; OR</p> <p>Official Academic IELTS test scores with an overall score of 7.0 and a minimum of 7.0 in each band or equivalent. It is possible to combine the results of two tests from the same provider to achieve the requirement, as long as the tests are within 6 months. For example, you could use scores from two IELTS tests to meet the requirement for English proficiency across the four IELTS components.</p> <p>COVID-19 Vaccination Record – Student must complete all required doses and to be taken 2 weeks apart from the flu vaccination.</p> <p>Immunisation Record</p> <p>National Police Record Check and/or Police clearance from country of residence</p> <p>Working with Children Check</p> <p>Diphtheria, Tetanus &amp; Pertussis – one documented dose of adult dTpa vaccine within the last 10 years</p> <p>Measles, Mumps &amp; Rubella – Student must be confirmed immune to measles, mumps and rubella via serology report or supply documented evidence of 2 doses of MMR at least 28 days apart</p> <p>Varicella – Student must be confirmed immune to varicella via serology report or have documented evidence of 2 doses of varicella given at least 28 days apart.</p> <p>Hepatitis A – Serology report shows evidence of Hep A antibodies or a course of 2 Hep A has commenced or been completed or a course of 3 Twinrix has commenced or been completed.</p> <p>Hepatitis B – Serology report shows a protective level of Hep B surface antibodies following completion of a primary course or a course of 3 Hep B or Twinrix has commenced. Those without protective level of Hep B will require review by infectious diseases specialist.</p> <p>Flu vaccination – Annual vaccination required and to be taken at least 2 weeks apart from COVID-19 vaccination.</p> <p>Hepatitis B Surface Antigen</p> <p>Hepatitis C</p> <p>HIV</p> <p>Tuberculosis</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-social-work',
    updated_at = NOW()
WHERE cricos_course_code = '104833E';


UPDATE courses SET
    course_description = '<p><br/>This qualification prepares you for work as an enrolled nurse working under the supervision of a registered nurse. The course covers the application of skills and knowledge required to provide nursing care for people across all areas of the health sector. Enrolled Nurses (commonly referred to as an EN) provide nursing support and care to patients within their scope of practice in a variety of health settings including hospital, general medical practices, community, aged care, and welfare areas.</p> <p>The Diploma of Nursing will equip you with the clinical skills, competencies and knowledge to work as a Division 2 Enrolled Nurse registered with the Nursing and Midwifery Board of Australia.</p>',
    total_course_duration = '2 years',
    offshore_tuition_fee = '15000',
    entry_requirements = '<p>18 years or older</p> <p>Completed Year 12 or equivalent</p> <p>Confirmation of the month and year you commenced and complete these courses</p> <p>Confirmation of whether you were enrolled into these courses part time or full time</p> <p>Confirmation of whether you undertook these courses face-to-face or online</p> <p>Confirmation that these courses were taught in English</p> <p>IELTS (academic module): Minimum overall score of 7 with a minimum score of 7 in listening, reading, speaking and 6.5 in writing</p> <p>OET: Minimum score of B in listening, reading, speaking and C+ in writing</p> <p>PTE Academic: Minimum overall score of 66 with no band less than 66 in listening, reading, speaking and 56 in writing</p> <p>TOEFL Internet based test (iBT): Minimum total score of 94 with a minimum score of 24 in listening, reading, writing and 23 in speaking</p> <p>Cambridge English: Advanced (CAE) or Proficiency (CPE): Minimum overall score of 185 with no less than 185 in listening, reading, speaking and 176 in writing</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-nursing',
    updated_at = NOW()
WHERE cricos_course_code = '114531C';


UPDATE courses SET
    course_description = '<p>Early childhood education and care (ECEC) is an academic, practice-based profession that promotes healthy early childhood development. ECEC strengthens families and communities by enhancing children’s cognitive and social-emotional skills while supporting the workforce participation of parents and caregivers.</p> <p>The Graduate Diploma of Early Childhood Education is a one-year course designed to equip you with a thorough understanding of early childhood development, pedagogy, curriculum, and the ethical and legislative requirements of the profession. You will also develop critical thinking, reflective practice, and continuous professional development skills.</p> <p>You will be introduced to the profession of early childhood teaching through an integrated curriculum that combines direct practice with theory, leadership, and advocacy, within a contemporary, play-based, and holistic approach. Field education placements will provide opportunities for experiential learning, allowing you to apply and develop theoretical knowledge across various early childhood teaching settings. Classroom activities, online tasks, and field practicums will help you connect theory to practice and apply your learning effectively.</p> <p>As an AE student based in the heart of Australia’s most vibrant cities, you join a diverse and friendly community of practice. You will benefit from plenty of opportunities to make lifelong friends, network, and grow as a global professional.</p>',
    total_course_duration = '1 year',
    offshore_tuition_fee = '25200',
    entry_requirements = '<p>An overall IELTS score of 6.5 with no band score below 6.5, or</p> <p>equivalent AE English placement test</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/graduate-diploma-of-early-childhood-education',
    updated_at = NOW()
WHERE cricos_course_code = '116494J';


UPDATE courses SET
    course_description = '<p>This course is ideal for those wishing to make a real difference for the well-being of people. A Diploma in Community Service is a qualification that enables you to become work-ready for roles in community services.</p> <p>This qualification prepares you to work effectively with individuals, families, groups and communities in a way that increases social and economic inclusion and enhances a person’s opportunity to reach their full potential.</p> <p>You will gain comprehensive skills in advocacy, case management, community program development, policy and research, and counselling.</p>',
    total_course_duration = '1 year',
    offshore_tuition_fee = '',
    entry_requirements = '<p>IELTS 5.5 or equivalent</p> <p>18 years or older</p> <p>Completion of Year 12 studies or equivalent</p> <p>Please see <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p> <p>National Police Record Check and/or Police clearance from country of residence</p> <p>Working with Children Check</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-community-services-1-year',
    updated_at = NOW()
WHERE cricos_course_code = '091282J';


UPDATE courses SET
    course_description = '<p>The International English Language Testing System (IELTS) is the fastest growing English test in the world and is widely accepted for enrolment into higher education institutions internationally (please visit <a class="rich-text-link" href="https://www.ielts.org/" rel="noreferrer" target="_blank"><b>https://www.ielts.org/</b></a> for more details).</p> <p>The IELTS Preparation course at Acknowledge Education is ideal for students wishing to improve their IELTS score in either the General or Academic modules. The course will fully prepare you for the test.</p> <p>You will:</p> <p>• Be familiarised with the nature and format of the exam</p> <p>• Be provided with numerous practice tests</p> <p>• Receive advice and strategies regarding the exam</p> <p>• Improve your overall language skills within the IELTS context</p> <p>• Be assessed with listening, reading, speaking and writing tests to assist you in your learning</p> <p>Universities and educational institutions normally require an overall IELTS band score of between 6.0 and 7.5. If you are interested in studying in Australia or New Zealand, this test is essential.</p>',
    total_course_duration = '20 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<p>Minimum 18 years old.</p> <p>A consistent IELTS band score of 5.5 is recommended as a minimum entry requirement for this course.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/ielts-preparation',
    updated_at = NOW()
WHERE cricos_course_code = '080629M';


UPDATE courses SET
    course_description = '<p>With almost forty years of experience in teaching young students, Acknowledge Education (formally known as Melbourne Language Centre) is recognised as a leader in providing tailored English preparation courses in Victoria, catering to high school students.</p> <p>The curriculum recognises the dual need for students to develop their general English language skills while also preparing them for future study in Australian high schools.</p> <p>Morning classes prioritise English language and communication, with students grouped based on their English proficiency as determined through rigorous testing during orientation. Throughout the day, significant time is dedicated to exploring daily concepts within the English language in both classroom and educative settings, preparing students for their pathway schools. Students continue to delve into academic language relevant to the Australian curriculum in the afternoon, maintaining groupings based on their English proficiency levels. As students advance in their language learning, they will have opportunities to apply their new skills during monthly excursions around the city. </p> <p>Specialist teachers are employed to teach mathematics and science, with students introduced to the concepts they can expect to study at their future schools. Homework is an integral part of the student program and is monitored by the classroom teacher on a daily basis. Excursions are organised regularly and include a range of cultural and social activities such as visits to museums, sightseeing tours, day hikes, sports days, and barbecues.</p> <p>The course is underpinned by:</p> <p>Content and Language Integrated Learning (CLIL), including maths, science, literature, history, geography, art and PE</p> <p>Aspects of Victorian Curriculum Foundation–10 for EAL</p> <p>Effective use of educational technology for both individual and group activities</p> <p>Regular cultural/social activities and excursions</p> <p>Excellence in teaching practice for all macro skills (reading, writing, listening and speaking) and enabling skills (pronunciation, spelling, vocabulary, grammar and punctuation)</p> <p>Regular liaison with a broad network of both independent and government pathway schools</p> <p><b>Teaching</b></p> <p>The teaching and assessment methods at Acknowledge Education include:</p> <p>Traditional classroom delivery</p> <p>Online support materials</p> <p>Consideration of different learning styles, abilities and preferences</p> <p>Group work and pair work, as well as individual assignments</p> <p>Interactive educational games and activities</p> <p>Regular formal and informal assessments and reports/feedback</p> <p>Acknowledge Education’s English for Junior Schools is specifically designed to prepare young children to transition into Australian schools.</p> <p>This course offers comprehensive, engaging and student-centred classes with high-quality resources that enrich the learning environment and facilitate language acquisition. Classes are kept small to ensure every student gets individual support from teachers.</p> <p>The course is underpinned by:</p> <p>Integration of Cambridge English: Young Learners (YLE)</p> <p>Content and Language Integrated Learning (CLIL), including maths, science, literature, history, geography, art and PE</p> <p>Aspects of Victorian Curriculum Foundation–10 for EAL</p> <p>Effective use of educational technology for both individual and group activities</p> <p>Regular cultural/social activities and excursions</p> <p>Various clubs (coding, cultural, debating, yoga, dance, music, and art)</p> <p>Excellence in teaching practice for all macro skills (reading, writing, listening and speaking) and enabling skills (pronunciation, spelling, vocabulary, grammar and punctuation)</p> <p>Small and focused classes with support for every student</p> <p>Regular liaison with a broad network of both independent and government pathway schools</p> <p><b>Teaching</b></p> <p>The teaching and assessment methods at Acknowledge Education include:</p> <p>Traditional classroom delivery</p> <p>Online support materials</p> <p>Consideration of different learning styles, abilities and preferences</p> <p>Group work and pair work, as well as individual assignments</p> <p>Regular formal and informal assessments and reports/feedback</p>',
    total_course_duration = '1–52 weeks',
    offshore_tuition_fee = '500',
    entry_requirements = '<p>Junior school preparation: 7–11 years old<br/>High school preparation: 12–18 years old</p> <p>Parents/legal custodians of students under 12 years old are required to drop children off at the classroom and sign them out.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools',
    updated_at = NOW()
WHERE cricos_course_code = '080627B';


UPDATE courses SET
    course_description = '<p>The Victorian Certificate of Education (VCE) is the certificate awarded to students upon the successful completion of secondary education in Victoria. It opens a wide range of paths into either further study at a university or vocational training institution, or entry into the workforce. It is an outstanding qualification that is recognised around the world.</p> <p>At Acknowledge Education, the close and respectful relationship between our teachers and students provides an optimal learning environment. When you study for the Victorian Certificate of Education (VCE), you can be assured that academic support is our highest priority and that our teaching staff are always on hand to assist you.</p>',
    total_course_duration = '2 year',
    offshore_tuition_fee = '19000',
    entry_requirements = '<p>• Completion of year 10<br/>• IELTS 5.0 or equivalent*<br/>• You can study <a class="rich-text-link" href="https://www.melblang.com.au/courses/english-for-secondary-schools/" rel="noreferrer" target="_blank">High School Preparation English</a> with us prior to course commencement of Year 11.</p> <p>• Completion of year 11<br/>• IELTS 5.0 or equivalent</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/vce-year-11-12',
    updated_at = NOW()
WHERE cricos_course_code = '032533F';


UPDATE courses SET
    course_description = '<p>English for Academic Purposes is designed to prepare you for your continuing tertiary education, at Certificate, Diploma, Undergraduate and Postgraduate levels.</p> <p>You are taught English language skills that will enable you to succeed in an academic environment. Presentation skills, essay writing, and comprehensive listening tasks all give you the best advantage when you go on to study at an Australian university. You are also exposed to advanced grammar and language skills</p>',
    total_course_duration = '1-52 weeks',
    offshore_tuition_fee = '500',
    entry_requirements = '<p>Minimum 18 years old.</p> <p>A consistent IELTS band of 5.5 is recommended as a minimum entry requirement for this course.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/english-for-academic-purposes',
    updated_at = NOW()
WHERE cricos_course_code = '080625D';


UPDATE courses SET
    course_description = '<p>At Acknowledge Education, you’ll study General English in a fun, relaxed and multicultural environment. Quickly pick up basic language skills to help you settle into life in Australia and deal with everyday situations with ease.The General English course focuses on communication skills within a variety of functional and situational contexts and improves your language skills (Reading, Writing, Listening and Speaking) in real life situations such as working, studying, travelling or living in Australia.</p> <p>We will support you during your English studies by:</p> <p>Offering extra-curricular classes including conversation club and social trips, focusing on speaking skill and cultural/social features of living in Australia</p> <p>Providing support sessions with an individual learning plan, focusing on all language skills including Reading, Writing, Listening, Speaking, Grammar, Vocabulary, Pronunciation and Punctuation</p> <p>Running academic and language skills development workshops</p> <p>Giving you access to online learning materials</p> <p>Arranging meetings with academic advisors, student support officers, and program coordinators</p> <p>General English is offered at Elementary, Pre-intermediate, Intermediate and Upper-intermediate levels and can serve as the perfect stepping stone to the study of English for Academic Purposes and IELTS courses.</p>',
    total_course_duration = '1–52 weeks',
    offshore_tuition_fee = '500',
    entry_requirements = '<p>Minimum 18 years old.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/general-english',
    updated_at = NOW()
WHERE cricos_course_code = '080628A';
